script:
// =====================================
// LOAD CHART.JS
// =====================================

if(!window.Chart){

    let script =
        document.createElement(
            "script"
        );

    script.src =
        "https://cdn.jsdelivr.net/npm/chart.js";

    script.onload = function(){

        load_asset_category_chart();

    };

    document.head.appendChild(
        script
    );

}else{

    load_asset_category_chart();

}



// =====================================
// LOAD CHART
// =====================================

function load_asset_category_chart(){

    frappe.call({

        method:
        "lab_assets.api.labwise_asset_category.get_asset_category_chart",

        callback: function(r){

            let data =
                r.message;

            if(
                !data ||
                !data.labels ||
                !data.labels.length
            ){

                return;

            }

            let canvas =
                root_element.querySelector(
                    "#assetChart"
                );

            let ctx =
                canvas.getContext("2d");



            // DESTROY OLD CHART

            if(window.assetChartObj){

                window.assetChartObj.destroy();

            }



            // PROFESSIONAL MUTED COLORS

            const colors = [

                '#3B82F6', // blue
                '#475569', // slate
                '#14B8A6', // teal
                '#8B5CF6', // violet
                '#F59E0B', // amber
                '#EF4444', // red
                '#0EA5E9'  // sky

            ];



            // DATASETS

            const datasets =
                data.datasets.map(
                    (d,index) => ({

                        label:
                            d.name,

                        data:
                            d.values,

                        backgroundColor:
                            colors[
                                index %
                                colors.length
                            ],

                        borderRadius: 2,

                        borderSkipped: false,

                        barThickness: 16,

                        maxBarThickness: 18

                    })
                );



            // CREATE CHART

            window.assetChartObj =
                new Chart(ctx, {

                    type: 'bar',

                    data: {

                        labels:
                            data.labels,

                        datasets:
                            datasets

                    },

                    options: {

                        responsive: true,

                        maintainAspectRatio: false,

                        indexAxis: 'y',

                        layout: {

                            padding: {

                                top: 5,
                                right: 10,
                                left: 5,
                                bottom: 5

                            }

                        },



                        plugins: {

                            legend: {

                                position: 'top',

                                align: 'start',

                                labels: {

                                    color:
                                        '#334155',

                                    font: {

                                        size: 11,

                                        family:
                                        'Inter'

                                    },

                                    boxWidth: 14,

                                    boxHeight: 8,

                                    padding: 14

                                }

                            },



                            tooltip: {

                                backgroundColor:
                                    '#111827',

                                titleColor:
                                    '#ffffff',

                                bodyColor:
                                    '#e5e7eb',

                                borderColor:
                                    '#374151',

                                borderWidth: 1,

                                padding: 10,

                                titleFont: {

                                    size: 12

                                },

                                bodyFont: {

                                    size: 11

                                }

                            }

                        },



                        scales: {

                            x: {

                                stacked: true,

                                grid: {

                                    color:
                                    'rgba(148,163,184,0.12)',

                                    drawBorder: false

                                },

                                ticks: {

                                    color:
                                        '#64748b',

                                    font: {

                                        size: 10

                                    }

                                }

                            },



                            y: {

                                stacked: true,

                                grid: {

                                    display: false,

                                    drawBorder: false

                                },

                                ticks: {

                                    color:
                                        '#334155',

                                    font: {

                                        size: 11,

                                        weight: '600'

                                    }

                                }

                            }

                        }

                    }

                });

        }

    });

}

// ======================================================
// INTERACTIVE ASSET DASHBOARD
// FULL UPDATED JS
// ======================================================



window.fiscal_years = [];

window.selected_fy_dates = null;



// ======================================================
// INITIAL LOAD
// ======================================================

setTimeout(() => {

    load_fiscal_years();

}, 500);



// ======================================================
// LOAD FINANCIAL YEARS
// ======================================================

function load_fiscal_years(){

    frappe.call({

        method:
            "frappe.client.get_list",

        args: {

            doctype:
                "Fiscal Year",

            fields: [

                "name",
                "year",
                "year_start_date",
                "year_end_date",
                "disabled"

            ],

            filters: {

                disabled: 0

            },

            order_by:
                "year_start_date desc",

            limit_page_length: 100

        },

        callback: function(r){

            window.fiscal_years =
                r.message || [];



            let select =
                root_element.querySelector(
                    "#fy_filter"
                );



            select.innerHTML = "";



            let all_option =
                document.createElement(
                    "option"
                );

            all_option.value = "";

            all_option.text =
                "All Financial Years";

            select.appendChild(
                all_option
            );



            (r.message || []).forEach(fy => {

                let option =
                    document.createElement(
                        "option"
                    );

                option.value =
                    fy.name;

                option.text =
                    fy.year;

                select.appendChild(
                    option
                );

            });



            if(r.message.length){

                select.value =
                    r.message[0].name;

            }



            load_laboratories();

        }

    });

}



// ======================================================
// LOAD LABORATORIES
// ======================================================

function load_laboratories(){

    frappe.call({

        method:
            "frappe.client.get_list",

        args: {

            doctype:
                "Soil Laboratory",

            fields: [

                "name",
                "lab_name"

            ],

            order_by:
                "lab_name asc",

            limit_page_length: 500

        },

        callback: function(r){

            let select =
                root_element.querySelector(
                    "#lab_filter"
                );



            select.innerHTML = `

                <option value="">
                    All Laboratories
                </option>

            `;



            (r.message || []).forEach(lab => {

                let option =
                    document.createElement(
                        "option"
                    );

                option.value =
                    lab.name;

                option.text =
                    lab.lab_name;

                select.appendChild(
                    option
                );

            });



            load_dashboard();



            root_element.querySelector(
                "#fy_filter"
            ).addEventListener(
                "change",
                load_dashboard
            );



            root_element.querySelector(
                "#lab_filter"
            ).addEventListener(
                "change",
                load_dashboard
            );

        }

    });

}



// ======================================================
// LOAD DASHBOARD DATA
// ======================================================

function load_dashboard(){

    let fy =
        root_element.querySelector(
            "#fy_filter"
        ).value;



    let laboratory =
        root_element.querySelector(
            "#lab_filter"
        ).value;



    window.selected_fy_dates = null;



    if(fy){

        let fy_doc =
            window.fiscal_years.find(
                x => x.name == fy
            );



        if(fy_doc){

            window.selected_fy_dates = {

                start_date:
                    fy_doc.year_start_date,

                end_date:
                    fy_doc.year_end_date

            };

        }

    }



    frappe.call({

        method:
            "lab_assets.api.asset_dashboard.get_dashboard_data",

        args: {

            fiscal_year:
                fy,

            laboratory:
                laboratory

        },

        callback: function(r){

            let d =
                r.message || {};



            // =====================================
            // KPI VALUES
            // =====================================

            root_element.querySelector(
                "#total_assets"
            ).innerText =
                d.total_assets || 0;



            root_element.querySelector(
                "#purchase_value"
            ).innerText =
                "₹ " +
                format_currency(
                    d.purchase_value || 0
                );



            root_element.querySelector(
                "#active_assets"
            ).innerText =
                d.active_assets || 0;



            root_element.querySelector(
                "#under_repair"
            ).innerText =
                d.under_repair || 0;



            root_element.querySelector(
                "#scrapped_assets"
            ).innerText =
                d.scrapped_assets || 0;



            root_element.querySelector(
                "#amc_expired"
            ).innerText =
                d.amc_expired || 0;



            root_element.querySelector(
                "#warranty_expired"
            ).innerText =
                d.warranty_expired || 0;



            root_element.querySelector(
                "#amc_expiring_soon"
            ).innerText =
                d.amc_expiring_soon || 0;



            root_element.querySelector(
                "#warranty_expiring_soon"
            ).innerText =
                d.warranty_expiring_soon || 0;



            // =====================================
            // AMC ALERT
            // =====================================

            let amc_card =
                root_element.querySelector(
                    "#amc_expiring_card"
                );



            if((d.amc_expiring_soon || 0) > 0){

                amc_card.classList.add(
                    "active-warning"
                );

            }

            else{

                amc_card.classList.remove(
                    "active-warning"
                );

            }



            // =====================================
            // WARRANTY ALERT
            // =====================================

            let warranty_card =
                root_element.querySelector(
                    "#warranty_expiring_card"
                );



            if((d.warranty_expiring_soon || 0) > 0){

                warranty_card.classList.add(
                    "active-warning"
                );

            }

            else{

                warranty_card.classList.remove(
                    "active-warning"
                );

            }

        }

    });

}



// ======================================================
// FORMAT CURRENCY
// ======================================================

function format_currency(value){

    return Number(value || 0)
    .toLocaleString(
        "en-IN"
    );

}



// ======================================================
// COMMON FILTERS
// ======================================================

function get_common_filters(){

    let filters = {};



    let lab =
        root_element.querySelector(
            "#lab_filter"
        ).value;



    if(lab){

        filters.location =
            lab;

    }



    if(window.selected_fy_dates){

        filters.purchase_date = [

            "Between",

            [

                window.selected_fy_dates.start_date,

                window.selected_fy_dates.end_date

            ]

        ];

    }



    return filters;

}



// ======================================================
// TOTAL ASSETS
// ======================================================

window.open_total_assets = function(){

    let filters =
        get_common_filters();

    frappe.route_options =
        filters;

    frappe.set_route(
        "List",
        "Asset"
    );

};



// ======================================================
// ACTIVE ASSETS
// ======================================================

window.open_active_assets = function(){

    let filters =
        get_common_filters();



    filters.docstatus = 1;



    filters.status = [

        "!=",
        "Scrapped"

    ];



    frappe.route_options =
        filters;

    frappe.set_route(
        "List",
        "Asset"
    );

};



// ======================================================
// SCRAPPED ASSETS
// ======================================================

window.open_scrapped_assets = function(){

    let filters =
        get_common_filters();

    filters.status =
        "Scrapped";

    frappe.route_options =
        filters;

    frappe.set_route(
        "List",
        "Asset"
    );

};



// ======================================================
// AMC EXPIRED
// ======================================================

window.open_amc_expired = function(){

    let filters =
        get_common_filters();

    filters.custom_amc_status =
        "Expired";

    frappe.route_options =
        filters;

    frappe.set_route(
        "List",
        "Asset"
    );

};



// ======================================================
// AMC EXPIRING SOON
// ======================================================

window.open_amc_expiring_soon = function(){

    let filters =
        get_common_filters();

    filters.custom_amc_status =
        "Expiring Soon";

    frappe.route_options =
        filters;

    frappe.set_route(
        "List",
        "Asset"
    );

};



// ======================================================
// WARRANTY EXPIRED
// ======================================================

window.open_warranty_expired = function(){

    let filters =
        get_common_filters();

    filters.custom_warranty_status =
        "Expired";

    frappe.route_options =
        filters;

    frappe.set_route(
        "List",
        "Asset"
    );

};



// ======================================================
// WARRANTY EXPIRING SOON
// ======================================================

window.open_warranty_expiring_soon = function(){

    let filters =
        get_common_filters();

    filters.custom_warranty_status =
        "Expiring Soon";

    frappe.route_options =
        filters;

    frappe.set_route(
        "List",
        "Asset"
    );

};



// ======================================================
// UNDER REPAIR
// ======================================================

window.open_under_repair = function(){

    let filters = {};



    let lab =
        root_element.querySelector(
            "#lab_filter"
        ).value;



    if(lab){

        filters.location =
            lab;

    }



    filters.repair_status =
        "Pending";



    frappe.route_options =
        filters;



    frappe.set_route(

        "List",
        "Asset Repair"

    );

};

style:
/* =====================================================
   GLOBAL
===================================================== */

*{
    box-sizing:border-box;
    margin:0;
    padding:0;
}



/* =====================================================
   MAIN DASHBOARD
===================================================== */

.asset-dashboard{

    width:100%;

    padding:18px;

    background:#f8fafc;

    border-radius:16px;

    font-family:
        Inter,
        "Segoe UI",
        sans-serif;

    overflow-x:hidden;

}



/* =====================================================
   HEADER
===================================================== */

.dashboard-header{

    margin-bottom:18px;

}

.dashboard-title{

    font-size:24px;

    font-weight:700;

    color:#0f172a;

}



/* =====================================================
   FILTER CONTAINER
===================================================== */

.filter-container{

    width:100%;

    margin-bottom:22px;

}



/* =====================================================
   FILTER BAR
===================================================== */

.filter-bar{

    display:flex;

    gap:16px;

    flex-wrap:wrap;

    align-items:end;

}



/* =====================================================
   FILTER GROUP
===================================================== */

.filter-group{

    display:flex;

    flex-direction:column;

    gap:6px;

    flex:1;

    min-width:240px;

}



/* =====================================================
   FILTER LABEL
===================================================== */

.filter-group label{

    font-size:12px;

    font-weight:600;

    color:#64748b;

}



/* =====================================================
   FILTER SELECT
===================================================== */

.filter-group select{

    width:100%;

    padding:10px 12px;

    border-radius:10px;

    border:1px solid #dbe2ea;

    background:#ffffff;

    font-size:13px;

    color:#334155;

    outline:none;

    transition:0.2s;

}



.filter-group select:focus{

    border-color:#2563eb;

    box-shadow:
        0 0 0 2px
        rgba(37,99,235,0.08);

}



/* =====================================================
   GRID
===================================================== */

.dashboard-grid{

    display:grid !important;

    grid-template-columns:
        repeat(auto-fill, minmax(260px, 1fr)) !important;

    gap:16px;

    width:100%;

}



/* =====================================================
   CARD
===================================================== */

.dashboard-card{

    width:100%;

    background:#ffffff;

    border-radius:16px;

    padding:18px;

    position:relative;

    overflow:hidden;

    border:
        1px solid #eef2f7;

    box-shadow:
        0 2px 10px
        rgba(15,23,42,0.05);

    transition:0.25s ease;

    min-height:180px;

    display:flex;

    flex-direction:column;

    justify-content:space-between;

}



.dashboard-card:hover{

    transform:translateY(-4px);

    box-shadow:
        0 12px 24px
        rgba(15,23,42,0.12);

}



/* =====================================================
   CARD TOP
===================================================== */

.card-top{

    display:flex;

    align-items:center;

    gap:12px;

}



/* =====================================================
   ICON
===================================================== */

.card-icon{

    width:52px;

    height:52px;

    border-radius:14px;

    display:flex;

    align-items:center;

    justify-content:center;

    font-size:24px;

    flex-shrink:0;

}



/* =====================================================
   TITLE
===================================================== */

.card-title{

    font-size:15px;

    font-weight:600;

    color:#334155;

    line-height:1.4;

}



/* =====================================================
   VALUE
===================================================== */

.card-value{

    margin-top:16px;

    font-size:32px;

    font-weight:700;

    color:#0f172a;

    letter-spacing:-0.5px;

    word-break:break-word;

}



/* =====================================================
   FOOTER
===================================================== */

.card-footer{

    margin-top:16px;

    padding-top:12px;

    border-top:
        1px solid #edf2f7;

    font-size:13px;

    font-weight:600;

    color:#2563eb;

    cursor:pointer;

    transition:0.2s;

}



.card-footer:hover{

    opacity:0.75;

}



/* =====================================================
   STANDARD COLORS
===================================================== */

.blue{
    border-top:4px solid #2563eb;
}

.green{
    border-top:4px solid #16a34a;
}

.purple{
    border-top:4px solid #7c3aed;
}

.orange{
    border-top:4px solid #ea580c;
}

.red{
    border-top:4px solid #dc2626;
}

.pink{
    border-top:4px solid #db2777;
}

.cyan{
    border-top:4px solid #0891b2;
}



/* =====================================================
   ICON BACKGROUNDS
===================================================== */

.blue .card-icon{
    background:#dbeafe;
}

.green .card-icon{
    background:#dcfce7;
}

.purple .card-icon{
    background:#ede9fe;
}

.orange .card-icon{
    background:#ffedd5;
}

.red .card-icon{
    background:#fee2e2;
}

.pink .card-icon{
    background:#fce7f3;
}

.cyan .card-icon{
    background:#cffafe;
}



/* =====================================================
   WARNING CARDS
===================================================== */

.amber{

    border-top:4px solid #f59e0b;

    background:
        linear-gradient(
            135deg,
            #ffffff,
            #fff7ed
        );

}



.yellow{

    border-top:4px solid #eab308;

    background:
        linear-gradient(
            135deg,
            #ffffff,
            #fefce8
        );

}



.amber .card-icon{
    background:#fef3c7;
}

.yellow .card-icon{
    background:#fef9c3;
}



/* =====================================================
   WARNING TAG
===================================================== */

.warning-tag{

    position:absolute;

    top:12px;

    right:12px;

    background:#f59e0b;

    color:#ffffff;

    font-size:10px;

    font-weight:700;

    padding:4px 8px;

    border-radius:20px;

    letter-spacing:0.3px;

    text-transform:uppercase;

}



/* =====================================================
   ACTIVE WARNING
===================================================== */

.active-warning{

    animation:
        warningGlow 2s infinite;

}



/* =====================================================
   WARNING VALUE COLORS
===================================================== */

.amber .card-value{

    color:#b45309;

}



.yellow .card-value{

    color:#a16207;

}



/* =====================================================
   GLOW ANIMATION
===================================================== */

@keyframes warningGlow{

    0%{

        box-shadow:
            0 0 0 rgba(245,158,11,0);

    }

    50%{

        box-shadow:
            0 0 20px rgba(245,158,11,0.35);

    }

    100%{

        box-shadow:
            0 0 0 rgba(245,158,11,0);

    }

}



/* =====================================================
   TABLET
===================================================== */

@media (max-width: 992px){

    .dashboard-grid{

        grid-template-columns:
            repeat(auto-fill, minmax(220px, 1fr)) !important;

    }

}



/* =====================================================
   MOBILE
===================================================== */

@media (max-width: 768px){

    .asset-dashboard{

        padding:12px;

        border-radius:12px;

    }

    .dashboard-title{

        font-size:20px;

    }

    .filter-bar{

        flex-direction:column;

        align-items:stretch;

    }

    .filter-group{

        width:100%;

        min-width:100%;

    }

    .dashboard-grid{

        grid-template-columns:1fr !important;

        gap:14px;

    }

    .dashboard-card{

        min-height:auto;

        padding:16px;

    }

    .card-icon{

        width:46px;

        height:46px;

        font-size:20px;

    }

    .card-value{

        font-size:26px;

    }

}



/* =====================================================
   SMALL MOBILE
===================================================== */

@media (max-width: 480px){

    .asset-dashboard{

        padding:10px;

    }

    .dashboard-title{

        font-size:18px;

    }

    .dashboard-card{

        padding:14px;

    }

    .card-title{

        font-size:13px;

    }

    .card-value{

        font-size:22px;

    }

    .card-footer{

        font-size:12px;

    }

}

script:
window.purchase_trend_fy = [];


// =====================================================
// INITIALIZE
// =====================================================

setTimeout(() => {

    load_trend_financial_years();

}, 500);



// =====================================================
// LOAD FINANCIAL YEARS
// =====================================================

function load_trend_financial_years() {

    frappe.call({

        method: "frappe.client.get_list",

        args: {

            doctype: "Fiscal Year",

            fields: [
                "name",
                "year"
            ],

            filters: {
                disabled: 0
            },

            order_by: "year_start_date desc",

            limit_page_length: 100

        },

        callback: function (r) {

            let fy_select =
                root_element.querySelector(
                    "#trend_financial_year"
                );



            fy_select.innerHTML = `

                <option value="">
                    All Financial Years
                </option>

            `;



            (r.message || []).forEach(fy => {

                fy_select.innerHTML += `

                    <option value="${fy.name}">
                        ${fy.year || fy.name}
                    </option>

                `;

            });



            load_trend_laboratories();

        }

    });

}



// =====================================================
// LOAD LABORATORIES
// =====================================================

function load_trend_laboratories() {

    frappe.call({

        method: "frappe.client.get_list",

        args: {

            doctype: "Warehouse",

            fields: ["name"],

            filters: {
                is_group: 0
            },

            order_by: "name asc",

            limit_page_length: 500

        },

        callback: function (r) {

            let lab_select =
                root_element.querySelector(
                    "#trend_laboratory"
                );



            lab_select.innerHTML = `

                <option value="">
                    All Laboratories
                </option>

            `;



            (r.message || []).forEach(lab => {

                lab_select.innerHTML += `

                    <option value="${lab.name}">
                        ${lab.name}
                    </option>

                `;

            });



            reload_all_charts();



            root_element.querySelector(
                "#trend_financial_year"
            ).addEventListener(
                "change",
                reload_all_charts
            );



            root_element.querySelector(
                "#trend_laboratory"
            ).addEventListener(
                "change",
                reload_all_charts
            );

        }

    });

}



// =====================================================
// RELOAD ALL CHARTS
// =====================================================

function reload_all_charts() {

    render_purchase_trend_chart();

    render_purchase_source_chart();

}



// =====================================================
// GET FILTERS
// =====================================================

function get_trend_filters() {

    return {

        financial_year:
            root_element.querySelector(
                "#trend_financial_year"
            ).value || "",

        laboratory:
            root_element.querySelector(
                "#trend_laboratory"
            ).value || ""

    };

}



// =====================================================
// LINE CHART
// =====================================================

function render_purchase_trend_chart() {

    let filters =
        get_trend_filters();



    frappe.call({

