script:
window.stock_fiscal_years = [];


// =====================================================
// INITIAL LOAD
// =====================================================

setTimeout(() => {

    load_stock_financial_years();

}, 500);



// =====================================================
// LOAD FINANCIAL YEARS
// =====================================================

function load_stock_financial_years() {

    frappe.call({

        method: "frappe.client.get_list",

        args: {

            doctype: "Fiscal Year",

            fields: [
                "name",
                "year",
                "year_start_date",
                "year_end_date"
            ],

            filters: {
                disabled: 0
            },

            order_by: "year_start_date desc",

            limit_page_length: 100
        },

        callback: function (r) {

            window.stock_fiscal_years =
                r.message || [];



            let fy_select =
                root_element.querySelector(
                    "#financial_year_filter"
                );



            fy_select.innerHTML = `

                <option value="">
                    All Financial Years
                </option>

            `;



            (r.message || []).forEach(fy => {

                fy_select.innerHTML += `

                    <option value="${fy.name}">
                        ${fy.year || fy.name}
                    </option>

                `;

            });



            load_laboratories();

        }

    });

}



// =====================================================
// LOAD LABORATORIES
// =====================================================

function load_laboratories() {

    frappe.call({

        method: "frappe.client.get_list",

        args: {

            doctype: "Warehouse",

            fields: ["name"],

            filters: {
                is_group: 0
            },

            order_by: "name asc",

            limit_page_length: 500
        },

        callback: function (r) {

            let lab_select =
                root_element.querySelector(
                    "#laboratory_filter"
                );



            lab_select.innerHTML = `

                <option value="">
                    All Laboratories
                </option>

            `;



            (r.message || []).forEach(lab => {

                lab_select.innerHTML += `

                    <option value="${lab.name}">
                        ${lab.name}
                    </option>

                `;

            });



            load_dashboard_data();



            root_element.querySelector(
                "#financial_year_filter"
            ).addEventListener(
                "change",
                load_dashboard_data
            );



            lab_select.addEventListener(
                "change",
                load_dashboard_data
            );

        }

    });

}



// =====================================================
// LOAD DASHBOARD DATA
// =====================================================

function load_dashboard_data() {

    let filters = get_filters();



    frappe.call({

        method:
            "lab_assets.api.stock_overview.get_stock_dashboard_data",

        args: {

            financial_year:
                filters.financial_year,

            laboratory:
                filters.laboratory

        },

        callback: function (r) {

            let d = r.message || {};



            root_element.querySelector(
                "#total_stock_value"
            ).innerText =
                "₹ " +
                format_currency(
                    d.total_stock_value || 0
                );



            root_element.querySelector(
                "#available_qty"
            ).innerText =
                format_number(
                    d.available_qty || 0
                );



            root_element.querySelector(
                "#purchase_value"
            ).innerText =
                "₹ " +
                format_currency(
                    d.purchase_value || 0
                );



            root_element.querySelector(
                "#material_issues"
            ).innerText =
                format_number(
                    d.material_issues || 0
                );



            root_element.querySelector(
                "#transfers"
            ).innerText =
                format_number(
                    d.transfers || 0
                );



            root_element.querySelector(
                "#damaged_alert_text"
            ).innerText =
                format_number(
                    d.damaged_items || 0
                ) +
                " Items Require Review";

        }

    });

}



// =====================================================
// GET FILTERS
// =====================================================

function get_filters() {

    return {

        financial_year:
            root_element.querySelector(
                "#financial_year_filter"
            ).value || "",

        laboratory:
            root_element.querySelector(
                "#laboratory_filter"
            ).value || ""

    };

}



// =====================================================
// GET FY DATES
// =====================================================

function get_fy_dates(fy_name) {

    let fy =
        (window.stock_fiscal_years || [])
        .find(x => x.name === fy_name);

    if (!fy) {

        return null;
    }

    return [
        fy.year_start_date,
        fy.year_end_date
    ];

}



// =====================================================
// FORMATTERS
// =====================================================

function format_currency(value) {

    return Number(value || 0)
        .toLocaleString(
            "en-IN",
            {
                minimumFractionDigits: 0,
                maximumFractionDigits: 2
            }
        );

}



function format_number(value) {

    return Number(value || 0)
        .toLocaleString("en-IN");

}



// =====================================================
// TOTAL STOCK VALUE
// =====================================================

window.open_total_stock = function () {

    open_stock_balance();

};



// =====================================================
// AVAILABLE STOCK
// =====================================================

window.open_available_stock = function () {

    open_stock_balance();

};



// =====================================================
// STOCK BALANCE REPORT
// =====================================================

function open_stock_balance() {

    let f = get_filters();

    frappe.route_options = {};



    frappe.route_options.company =
        "Soil Survey and Soil Conservation Department";



    // =====================================
    // NO FILTERS
    // =====================================

    if (
        !f.financial_year &&
        !f.laboratory
    ) {

        frappe.route_options = {

            company:
                "Soil Survey and Soil Conservation Department",

            include_zero_stock_items: 1

        };



        frappe.set_route(
            "query-report",
            "Stock Balance"
        );

        return;
    }



    // =====================================
    // LAB FILTER
    // =====================================

    if (f.laboratory) {

        frappe.route_options.warehouse = [
            f.laboratory
        ];

    }



    // =====================================
    // FY FILTER
    // =====================================

    let fy_dates =
        get_fy_dates(
            f.financial_year
        );



    if (fy_dates) {

        frappe.route_options.from_date =
            fy_dates[0];

        frappe.route_options.to_date =
            fy_dates[1];

    }



    frappe.set_route(
        "query-report",
        "Stock Balance"
    );

}



// =====================================================
// PURCHASE RECEIPTS
// =====================================================

window.open_purchase_receipts = function () {

    let f = get_filters();



    frappe.route_options = {

        docstatus: 1,

        custom_is_stock_item: 1

    };



    // =====================================
    // LAB FILTER
    // =====================================

    if (f.laboratory) {

        frappe.route_options.warehouse =
            f.laboratory;

    }



    // =====================================
    // FY FILTER
    // =====================================

    let fy_dates =
        get_fy_dates(
            f.financial_year
        );



    if (fy_dates) {

        frappe.route_options.posting_date = [

            "Between",

            fy_dates

        ];

    }



    frappe.set_route(

        "List",

        "Purchase Receipt"

    );

};



// =====================================================
// MATERIAL ISSUES
// =====================================================

window.open_material_issues = function () {

    let f = get_filters();



    frappe.route_options = {

        stock_entry_type: "Material Issue",

        docstatus: 1,

        custom_is_broken_item_entry: 0

    };



    // =====================================
    // LAB FILTER
    // =====================================

    if (f.laboratory) {

        frappe.route_options.from_warehouse =
            f.laboratory;

    }



    // =====================================
    // FY FILTER
    // =====================================

    let fy_dates =
        get_fy_dates(
            f.financial_year
        );



    if (fy_dates) {

        frappe.route_options.posting_date = [

            "Between",

            fy_dates

        ];

    }



    frappe.set_route(

        "List",

        "Stock Entry"

    );

};



// =====================================================
// TRANSFERS
// =====================================================

window.open_transfers = function () {

    let f = get_filters();



    frappe.route_options = {

        stock_entry_type: "Material Transfer",

        docstatus: 1

    };



    // =====================================
    // LAB FILTER
    // =====================================

    if (f.laboratory) {

        frappe.route_options.from_warehouse =
            f.laboratory;

    }



    // =====================================
    // FY FILTER
    // =====================================

    let fy_dates =
        get_fy_dates(
            f.financial_year
        );



    if (fy_dates) {

        frappe.route_options.posting_date = [

            "Between",

            fy_dates

        ];

    }



    frappe.set_route(

        "List",

        "Stock Entry"

    );

};



// =====================================================
// DAMAGED ITEMS
// =====================================================

window.open_damaged_items = function () {

    let f = get_filters();



    frappe.route_options = {

        docstatus: 1

    };



    // =====================================
    // LAB FILTER
    // =====================================

    if (f.laboratory) {

        frappe.route_options.lab_location =
            f.laboratory;

    }



    // =====================================
    // FY FILTER
    // =====================================

    let fy_dates =
        get_fy_dates(
            f.financial_year
        );



    if (fy_dates) {

        frappe.route_options.broken_date = [

            "Between",

            fy_dates

        ];

    }



    frappe.set_route(

        "List",

        "Broken Item Register"

    );

};

