// ======================================================
// GLOBAL VARIABLES
// ======================================================

window.asset_category_chart = null;

window.fiscal_years = [];



// ======================================================
// INITIAL LOAD
// ======================================================

setTimeout(() => {

    load_fiscal_years();

}, 600);



// ======================================================
// LOAD FINANCIAL YEARS
// ======================================================

function load_fiscal_years(){

    frappe.call({

        method:
            "frappe.client.get_list",

        args:{

            doctype:
                "Fiscal Year",

            fields:[

                "name",
                "year",
                "year_start_date",
                "year_end_date"

            ],

            order_by:
                "year_start_date desc",

            limit_page_length:100

        },

        callback:function(r){

            let select =
                root_element.querySelector(
                    "#fy_filter"
                );



            select.innerHTML = "";



            // =========================================
            // ALL OPTION
            // =========================================

            let all_option =
                document.createElement(
                    "option"
                );

            all_option.value = "";

            all_option.text =
                "All Financial Years";

            select.appendChild(
                all_option
            );



            // =========================================
            // FY OPTIONS
            // =========================================

            (r.message || []).forEach(fy => {

                let option =
                    document.createElement(
                        "option"
                    );

                option.value =
                    fy.name;

                option.text =
                    fy.year;

                select.appendChild(
                    option
                );

            });



            // =========================================
            // LOAD DASHBOARD
            // =========================================

            load_dashboard();



            // =========================================
            // FILTER CHANGE
            // =========================================

            select.addEventListener(

                "change",

                load_dashboard

            );

        }

    });

}



// ======================================================
// LOAD DASHBOARD
// ======================================================

function load_dashboard(){

    let fy =
        root_element.querySelector(
            "#fy_filter"
        ).value;



    // ==================================================
    // KPI DATA
    // ==================================================

    frappe.call({

        method:
            "lab_assets.api.asset_dashboard.get_employee_dashboard_data",

        args:{

            fiscal_year: fy

        },

        callback:function(r){

            let d =
                r.message || {};



            // =========================================
            // KPI VALUES
            // =========================================

            root_element.querySelector(
                "#total_assets"
            ).innerText =

                d.total_assets || 0;



            root_element.querySelector(
                "#purchase_value"
            ).innerText =

                "₹ " +

                Number(

                    d.purchase_value || 0

                ).toLocaleString(
                    "en-IN"
                );



            root_element.querySelector(
                "#active_assets"
            ).innerText =

                d.active_assets || 0;



            root_element.querySelector(
                "#under_repair"
            ).innerText =

                d.under_repair || 0;



            root_element.querySelector(
                "#scrapped_assets"
            ).innerText =

                d.scrapped_assets || 0;



            root_element.querySelector(
                "#amc_expired"
            ).innerText =

                d.amc_expired || 0;



            root_element.querySelector(
                "#warranty_expired"
            ).innerText =

                d.warranty_expired || 0;

        }

    });



    // ==================================================
    // CHART DATA
    // ==================================================

    frappe.call({

        method:
            "lab_assets.api.asset_dashboard.get_asset_category_summary",

        callback:function(r){

            let data =
                r.message || {};



            // =========================================
            // LAB NAME
            // =========================================

            root_element.querySelector(
                "#lab_name"
            ).innerText =

                "Lab : " +

                (data.labs || []).join(", ");



            // =========================================
            // PREPARE DATA
            // =========================================

            let labels = [];

            let values = [];



            (data.categories || []).forEach(row => {

                labels.push(

                    row.asset_category || "Others"

                );



                values.push(

                    row.count || 0

                );

            });



            // =========================================
            // DESTROY OLD CHART
            // =========================================

            if(window.asset_category_chart){

                window.asset_category_chart.destroy();

            }



            // =========================================
            // CREATE CHART
            // =========================================

            let ctx =
                root_element.querySelector(
                    "#assetCategoryChart"
                );



            window.asset_category_chart =
                new Chart(

                    ctx,

                    {

                        type:"doughnut",

                        data:{

                            labels:labels,

                            datasets:[{

                                data:values,

                                borderWidth:1

                            }]

                        },

                        options:{

                            responsive:true,

                            maintainAspectRatio:false,

                            cutout:"72%",



                            plugins:{

                                legend:{

                                    position:"bottom",

                                    labels:{

                                        padding:12,

                                        boxWidth:12,

                                        font:{

                                            size:11

                                        }

                                    }

                                }

                            }

                        }

                    }

                );

        }

    });

}

