script:
if(typeof Chart === "undefined"){

    frappe.require(
        "https://cdn.jsdelivr.net/npm/chart.js"
    );

}

window.stock_chart = null;



setTimeout(() => {

    load_financial_years();

}, 600);



// =====================================================
// LOAD FY
// =====================================================

function load_financial_years(){

    frappe.call({

        method:"frappe.client.get_list",

        args:{

            doctype:"Fiscal Year",

            fields:[
                "name",
                "year"
            ],

            filters:{
                disabled:0
            },

            order_by:"year_start_date desc"

        },

        callback:function(r){

            let select =
                root_element.querySelector(
                    "#financial_year_filter"
                );



            select.innerHTML = `

                <option value="">
                    All Financial Years
                </option>

            `;



            (r.message || []).forEach(fy => {

                select.innerHTML += `

                    <option value="${fy.name}">
                        ${fy.year}
                    </option>

                `;

            });



            load_dashboard();



            select.addEventListener(
                "change",
                load_dashboard
            );

        }

    });

}



// =====================================================
// LOAD DASHBOARD
// =====================================================

function load_dashboard(){

    let fy =
        root_element.querySelector(
            "#financial_year_filter"
        ).value;



    // =================================================
    // KPI DATA
    // =================================================

    frappe.call({

        method:
            "lab_assets.api.stock_overview.get_employee_stock_dashboard",

        args:{
            financial_year: fy
        },

        callback:function(r){

            let d =
                r.message || {};



            root_element.querySelector(
                "#total_stock_value"
            ).innerText =

                "₹ " +

                Number(
                    d.total_stock_value || 0
                ).toLocaleString("en-IN");



            root_element.querySelector(
                "#available_qty"
            ).innerText =

                Number(
                    d.available_qty || 0
                ).toLocaleString("en-IN");



            root_element.querySelector(
                "#purchase_value"
            ).innerText =

                "₹ " +

                Number(
                    d.purchase_value || 0
                ).toLocaleString("en-IN");



            root_element.querySelector(
                "#material_issues"
            ).innerText =
                d.material_issues || 0;



            root_element.querySelector(
                "#transfers"
            ).innerText =
                d.transfers || 0;



            root_element.querySelector(
                "#damaged_alert_text"
            ).innerText =

                (d.damaged_items || 0) +

                " Items Require Review";

        }

    });



    // =================================================
    // CHART DATA
    // =================================================

    frappe.call({

        method:
            "lab_assets.api.stock_overview.get_stock_group_distribution",

        callback:function(r){

            let data =
                r.message || {};



            // =========================================
            // LAB NAME
            // =========================================

            root_element.querySelector(
                "#warehouse_name"
            ).innerText =

                "Lab Name : " +

                (data.labs || []).join(", ");



            // =========================================
            // CHART DATA
            // =========================================

            let labels = [];

            let values = [];



            (data.groups || []).forEach(row => {

                labels.push(
                    row.item_group || "Others"
                );



                values.push(
                    row.qty || 0
                );

            });



            // =========================================
            // DESTROY OLD
            // =========================================

            if(window.stock_chart){

                window.stock_chart.destroy();

            }



            // =========================================
            // CREATE CHART
            // =========================================

            let ctx =
                root_element.querySelector(
                    "#stockCategoryChart"
                );



            window.stock_chart =
                new Chart(

                    ctx,

                    {

                        type:"doughnut",

                        data:{

                            labels:labels,

                            datasets:[{

                                data:values,

                                borderWidth:1

                            }]

                        },

                        options:{

                            responsive:true,

                            maintainAspectRatio:false,

                            cutout:"72%",

                            plugins:{

                                legend:{

                                    position:"bottom",

                                    labels:{

                                        padding:12,

                                        boxWidth:12,

                                        font:{
                                            size:11
                                        }

                                    }

                                }

                            }

                        }

                    }

                );

        }

    });

}

